ALTER TABLE creative_assets
    ADD COLUMN mood text NOT NULL DEFAULT '' CHECK (char_length(mood) <= 80),
    ADD COLUMN energy text NOT NULL DEFAULT 'low' CHECK (energy IN ('low', 'medium', 'high')),
    ADD COLUMN use_when text NOT NULL DEFAULT '' CHECK (char_length(use_when) <= 240),
    ADD COLUMN avoid_when text NOT NULL DEFAULT '' CHECK (char_length(avoid_when) <= 240);

